import{_ as a,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const c=JSON.parse('{"title":"第 26 章 专家助手库：11 位内置专家与自定义（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第26章 专家助手库：11 位内置专家与自定义（易懂版）.md","filePath":"easy/第26章 专家助手库：11 位内置专家与自定义（易懂版）.md"}'),n={name:"easy/第26章 专家助手库：11 位内置专家与自定义（易懂版）.md"};function s(l,t,i,d,h,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-26-章-专家助手库-11-位内置专家与自定义-易懂版" tabindex="-1">第 26 章 专家助手库：11 位内置专家与自定义（易懂版） <a class="header-anchor" href="#第-26-章-专家助手库-11-位内置专家与自定义-易懂版" aria-label="Permalink to &quot;第 26 章 专家助手库：11 位内置专家与自定义（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 <a href="./../bluebook/第五篇 平台能力全景/第 26 章 专家助手库：11 位内置专家与自定义.html">第 26 章 专家助手库：11 位内置专家与自定义（完整版）</a>。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>我自带一支&quot;专家顾问团&quot;——要找挑刺的、找管进度的、找审代码的，直接点名。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>公司里开会，你不会让所有人干同一件事：</p><ul><li>有人负责<strong>挑毛病</strong>（这个方案哪里不靠谱？）；</li><li>有人负责<strong>盯进度</strong>（今天做到哪了？）；</li><li>有人负责<strong>把质量关</strong>（这段代码有没有坑？）。</li></ul><p><strong>这 11 位专家，就是三种&quot;角色&quot;的化身。</strong> 你点名，他就用那个角色的方式跟你说话。</p><h2 id="三位最常用的专家-记住这三个就够" tabindex="-1">三位最常用的专家（记住这三个就够） <a class="header-anchor" href="#三位最常用的专家-记住这三个就够" aria-label="Permalink to &quot;三位最常用的专家（记住这三个就够）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>专家角色</th><th>他擅长什么</th><th>什么时候叫他</th></tr></thead><tbody><tr><td><strong>现实检验者</strong></td><td>给热情泼冷水，找风险</td><td>方案太顺、感觉&quot;是不是想太美了&quot;</td></tr><tr><td><strong>项目经理</strong></td><td>拆任务、排优先级、盯进度</td><td>事情多、乱、不知道先干哪个</td></tr><tr><td><strong>代码审查员</strong></td><td>抠细节、找隐患</td><td>代码要上线前</td></tr></tbody></table><h2 id="怎么点名" tabindex="-1">怎么点名 <a class="header-anchor" href="#怎么点名" aria-label="Permalink to &quot;怎么点名&quot;">​</a></h2><p><strong>直接说就行</strong>，不用记什么命令：</p><blockquote><p>&quot;让现实检验者看看我这个方案有什么风险。&quot; &quot;用项目经理的方式，帮我把这周的事排一下。&quot;</p></blockquote><h2 id="还能自己造专家" tabindex="-1">还能自己造专家 <a class="header-anchor" href="#还能自己造专家" aria-label="Permalink to &quot;还能自己造专家&quot;">​</a></h2><p>想要一个&quot;永远按我们公司风格写文案的人&quot;？<strong>把要求写下来，做成自定义专家</strong>，以后每次点名，他都按这套规矩干活。这跟做 Skill（第 17 章）是同一个思路。</p><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 用专家当&quot;夸夸群&quot;——<strong>专家最大的价值是挑错，别只想要赞美</strong>；</li><li>❌ 不告诉专家背景——<strong>先给资料和约束，他才能专业</strong>；</li><li>❌ 造了专家不用——<strong>造完要进日常流程</strong>。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>专家助手 = 给同一个我，换上不同专业角色的&quot;人格与标准&quot;。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>想想你手头最纠结的那件事——<strong>你是需要有人挑刺，还是需要有人帮你排顺序？</strong> 那就是你该点的专家。</p><p>👉 [下一章：团队模板与工作流编排（易懂版）](第27章 团队模板与工作流编排（易懂版）.md)</p>',22)])])}const q=a(n,[["render",s]]);export{c as __pageData,q as default};
